// Drops bots (hidden honeypot field filled) and incomplete submissions,
// then builds the notification email for Mallory.
const b = $input.first().json.body || {};
const clean = (v, max = 500) => String(v ?? '').trim().slice(0, max);
const esc = (v) => clean(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

if (clean(b.website)) return [];
const lead = {
  fullName: clean(b.fullName, 120),
  phone: clean(b.phone, 40),
  email: clean(b.email, 160),
  address: clean(b.address, 240),
  timeframe: clean(b.timeframe, 60) || 'Not specified',
  notes: clean(b.notes, 2000),
};
if (!lead.fullName || !lead.address || !(lead.phone || lead.email)) return [];
if (lead.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(lead.email)) lead.email = '';

const received = new Date().toLocaleString('en-US', { timeZone: 'America/Chicago', dateStyle: 'medium', timeStyle: 'short' });
const tel = lead.phone.replace(/[^0-9+]/g, '');
const maps = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(lead.address);
const row = (k, v) => `<tr><td style="padding:6px 14px 6px 0;color:#6b6b6b;white-space:nowrap;vertical-align:top">${k}</td><td style="padding:6px 0;color:#1a1a1a">${v}</td></tr>`;

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px">
<div style="background:#0b0b0b;color:#fff;padding:14px 18px;border-bottom:4px solid #b8102e"><strong>New Home Valuation Lead</strong></div>
<div style="padding:16px 18px;border:1px solid #e3e3e3;border-top:0">
<p style="margin:0 0 12px">${esc(lead.fullName)} requested a free home valuation. Follow up soon.</p>
<table style="border-collapse:collapse;font-size:14px">
${row('Name', esc(lead.fullName))}
${row('Phone', lead.phone ? `<a href="tel:${tel}">${esc(lead.phone)}</a>` : '—')}
${row('Email', lead.email ? `<a href="mailto:${esc(lead.email)}">${esc(lead.email)}</a>` : '—')}
${row('Property', `<a href="${maps}">${esc(lead.address)}</a>`)}
${row('Timeframe', esc(lead.timeframe))}
${row('Notes', lead.notes ? esc(lead.notes).replace(/\n/g, '<br>') : '—')}
${row('Received', received)}
</table>
<p style="margin:14px 0 0;color:#6b6b6b;font-size:12px">Source: Home Valuation landing page (QR). Reply to this email to respond to the lead directly.</p>
</div></div>`;

return [{ json: { ...lead, received, subject: `New Home Valuation Lead: ${lead.fullName} (${lead.address})`, html } }];
